BEGIN;
CREATE TABLE IF NOT EXISTS aggregate_versions(tenant_id uuid NOT NULL,aggregate_id uuid NOT NULL,version bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,aggregate_id));
CREATE TABLE IF NOT EXISTS outbox_consumer_receipts(tenant_id uuid NOT NULL,consumer text NOT NULL,message_id uuid NOT NULL,fencing_token bigint NOT NULL,processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,consumer,message_id));
CREATE TABLE IF NOT EXISTS projection_checkpoints(tenant_id uuid NOT NULL,projection text NOT NULL,aggregate_id uuid NOT NULL,sequence bigint NOT NULL,state_hash text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,projection,aggregate_id));
CREATE TABLE IF NOT EXISTS patient_impact_edges(tenant_id uuid NOT NULL,patient_id uuid NOT NULL,source_artifact text NOT NULL,source_version text NOT NULL,derived_artifact text NOT NULL,impact_kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,patient_id,source_artifact,source_version,derived_artifact));
CREATE TABLE IF NOT EXISTS audit_chain_v2(tenant_id uuid NOT NULL,id uuid NOT NULL,previous_hash text NOT NULL,entry_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS break_glass_reviews(tenant_id uuid NOT NULL,id uuid PRIMARY KEY,patient_id uuid NOT NULL,actor_id uuid NOT NULL,reason text NOT NULL,expires_at timestamptz NOT NULL,review_status text NOT NULL DEFAULT 'PENDING',reviewer_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clinical_safety_findings(tenant_id uuid NOT NULL,id uuid PRIMARY KEY,patient_id uuid,severity text NOT NULL,kind text NOT NULL,owner_id uuid NOT NULL,recovery_plan text NOT NULL,status text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['aggregate_versions','outbox_consumer_receipts','projection_checkpoints','patient_impact_edges','audit_chain_v2','break_glass_reviews','clinical_safety_findings'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=app.current_tenant()) WITH CHECK (tenant_id=app.current_tenant())',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION app.prevent_append_only_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'APPEND_ONLY_MUTATION_FORBIDDEN'; END $$;
DROP TRIGGER IF EXISTS audit_chain_v2_append_only ON audit_chain_v2;CREATE TRIGGER audit_chain_v2_append_only BEFORE UPDATE OR DELETE ON audit_chain_v2 FOR EACH ROW EXECUTE FUNCTION app.prevent_append_only_mutation();
COMMIT;
